// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAdminV1Models 列出对外模型与各自的路由
	// (GET /admin/v1/models)
	GetAdminV1Models(w http.ResponseWriter, r *http.Request)
	// DeleteAdminV1ModelsName 删除一个对外模型
	// (DELETE /admin/v1/models/{name})
	DeleteAdminV1ModelsName(w http.ResponseWriter, r *http.Request, name string)
	// PutAdminV1ModelsName 新建或修改一个对外模型及其全部路由
	// (PUT /admin/v1/models/{name})
	PutAdminV1ModelsName(w http.ResponseWriter, r *http.Request, name string)
	// PostAdminV1ModelsNameTest 按路由发一次最小请求，检查这个模型能否调用
	// (POST /admin/v1/models/{name}/test)
	PostAdminV1ModelsNameTest(w http.ResponseWriter, r *http.Request, name string)
	// GetAdminV1Providers 列出模型来源与健康状态
	// (GET /admin/v1/providers)
	GetAdminV1Providers(w http.ResponseWriter, r *http.Request)
	// DeleteAdminV1ProvidersId 删除一个模型来源
	// (DELETE /admin/v1/providers/{id})
	DeleteAdminV1ProvidersId(w http.ResponseWriter, r *http.Request, id string)
	// PutAdminV1ProvidersId 新建或修改一个模型来源
	// (PUT /admin/v1/providers/{id})
	PutAdminV1ProvidersId(w http.ResponseWriter, r *http.Request, id string)
	// PostAdminV1ProvidersIdTest 用来源的 key 请求一次 /models，检查地址与 key
	// (POST /admin/v1/providers/{id}/test)
	PostAdminV1ProvidersIdTest(w http.ResponseWriter, r *http.Request, id string)
	// GetHealthz 进程存活
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// GetReadyz 依赖可用，并返回服务端接受的客户端 schema 版本
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
	// GetV1AppReleases 应用安装包的发布清单
	// (GET /v1/app/releases)
	GetV1AppReleases(w http.ResponseWriter, r *http.Request)
	// PostV1AuthEmailVerifyConfirm 用验证码确认当前账号的邮箱
	// (POST /v1/auth/email/verify/confirm)
	PostV1AuthEmailVerifyConfirm(w http.ResponseWriter, r *http.Request)
	// PostV1AuthEmailVerifyRequest 给当前账号的邮箱发一封验证码邮件
	// (POST /v1/auth/email/verify/request)
	PostV1AuthEmailVerifyRequest(w http.ResponseWriter, r *http.Request)
	// PostV1AuthLogin 登录，每台设备一个会话（按来源地址限流，与注册共用一个令牌桶）
	// (POST /v1/auth/login)
	PostV1AuthLogin(w http.ResponseWriter, r *http.Request)
	// PostV1AuthLogout 退出当前设备
	// (POST /v1/auth/logout)
	PostV1AuthLogout(w http.ResponseWriter, r *http.Request)
	// PostV1AuthPasswordForgot 向账号登记的邮箱发送重设密码验证码
	// (POST /v1/auth/password/forgot)
	PostV1AuthPasswordForgot(w http.ResponseWriter, r *http.Request)
	// PostV1AuthPasswordReset 用验证码重设密码，并作废该账号的全部会话
	// (POST /v1/auth/password/reset)
	PostV1AuthPasswordReset(w http.ResponseWriter, r *http.Request)
	// PostV1AuthRefresh 用刷新令牌换一组新令牌，旧的两枚立即失效（按账号与来源地址限流）
	// (POST /v1/auth/refresh)
	PostV1AuthRefresh(w http.ResponseWriter, r *http.Request)
	// PostV1AuthRegister 注册并登录当前设备（按来源地址限流，与登录共用一个令牌桶）
	// (POST /v1/auth/register)
	PostV1AuthRegister(w http.ResponseWriter, r *http.Request)
	// DeleteV1Backups 清空该账号的全部整库备份
	// (DELETE /v1/backups)
	DeleteV1Backups(w http.ResponseWriter, r *http.Request)
	// GetV1Backups 列出整库备份，新的在前
	// (GET /v1/backups)
	GetV1Backups(w http.ResponseWriter, r *http.Request)
	// PostV1Backups 上传一份版本库备份 zip，超过保留份数时删最旧的
	// (POST /v1/backups)
	PostV1Backups(w http.ResponseWriter, r *http.Request, params PostV1BackupsParams)
	// DeleteV1BackupsId 删除一份备份
	// (DELETE /v1/backups/{id})
	DeleteV1BackupsId(w http.ResponseWriter, r *http.Request, id string)
	// GetV1BackupsId 下载备份；客户端按现有的版本库恢复流程预检
	// (GET /v1/backups/{id})
	GetV1BackupsId(w http.ResponseWriter, r *http.Request, id string)
	// GetV1BlobsSha256 下载附件
	// (GET /v1/blobs/{sha256})
	GetV1BlobsSha256(w http.ResponseWriter, r *http.Request, sha256 string)
	// HeadV1BlobsSha256 附件是否已上传
	// (HEAD /v1/blobs/{sha256})
	HeadV1BlobsSha256(w http.ResponseWriter, r *http.Request, sha256 string)
	// PutV1BlobsSha256 上传附件，服务端核对哈希
	// (PUT /v1/blobs/{sha256})
	PutV1BlobsSha256(w http.ResponseWriter, r *http.Request, sha256 string)
	// DeleteV1Cloud 清除该账号的全部云端数据
	// (DELETE /v1/cloud)
	DeleteV1Cloud(w http.ResponseWriter, r *http.Request)
	// PostV1Feedback 提交一条应用内反馈
	// (POST /v1/feedback)
	PostV1Feedback(w http.ResponseWriter, r *http.Request)
	// PostV1LlmChatCompletions OpenAI Chat Completions 代理
	// (POST /v1/llm/chat/completions)
	PostV1LlmChatCompletions(w http.ResponseWriter, r *http.Request)
	// PostV1LlmEmbeddings OpenAI Embeddings 代理，支持批量
	// (POST /v1/llm/embeddings)
	PostV1LlmEmbeddings(w http.ResponseWriter, r *http.Request, params PostV1LlmEmbeddingsParams)
	// PostV1LlmEmbeddingsLookup 批量查找已缓存的嵌入向量
	// (POST /v1/llm/embeddings/lookup)
	PostV1LlmEmbeddingsLookup(w http.ResponseWriter, r *http.Request)
	// GetV1LlmModels 当前可用的模型，OpenAI 列表格式
	// (GET /v1/llm/models)
	GetV1LlmModels(w http.ResponseWriter, r *http.Request)
	// GetV1LlmQuota 今日用量与额度
	// (GET /v1/llm/quota)
	GetV1LlmQuota(w http.ResponseWriter, r *http.Request)
	// DeleteV1Me 删除账号，连同同步序列、附件、备份与用量一并删除
	// (DELETE /v1/me)
	DeleteV1Me(w http.ResponseWriter, r *http.Request)
	// GetV1Me 当前账号
	// (GET /v1/me)
	GetV1Me(w http.ResponseWriter, r *http.Request)
	// DeleteV1SyncCommits 清空该账号的提交序列，服务端 head 重置为 0
	// (DELETE /v1/sync/commits)
	DeleteV1SyncCommits(w http.ResponseWriter, r *http.Request)
	// GetV1SyncCommits 拉取 seq 大于 after 的提交
	// (GET /v1/sync/commits)
	GetV1SyncCommits(w http.ResponseWriter, r *http.Request, params GetV1SyncCommitsParams)
	// PostV1SyncCommits 推送本机提交
	// (POST /v1/sync/commits)
	PostV1SyncCommits(w http.ResponseWriter, r *http.Request)
	// GetV1SyncHead 服务端序列的最新位置
	// (GET /v1/sync/head)
	GetV1SyncHead(w http.ResponseWriter, r *http.Request)
	// PostV1TelemetryActive 匿名上报一次活跃
	// (POST /v1/telemetry/active)
	PostV1TelemetryActive(w http.ResponseWriter, r *http.Request)
}

